let
  f = builtins.getFlake "path:/home/mei/nixos-wt/thinkpad-zero-touch-install-wave2";
  probe = name:
    let
      c = f.isoConfig.${name}.config;
      u = c.systemd.services.nixos-autoinstall;
      units = c.systemd.units;
      shell = c.systemd.services.iso-install-rescue-shell;
    in {
      wantedBy = u.wantedBy;
      wants = u.wants;
      after = u.after;
      unitConfig = u.unitConfig;
      serviceConfig = {
        inherit (u.serviceConfig) Type RemainAfterExit StandardOutput StandardError;
      };
      script = u.script;
      shellServiceConfig = shell.serviceConfig;
      unitText = units."nixos-autoinstall.service".text or "ABSENT";
      rescueTargetText = units."iso-install-rescue.target".text or "ABSENT";
      shellText = units."iso-install-rescue-shell.service".text or "ABSENT";
      kernelParams = c.boot.kernelParams;
      sshdEnabled = c.services.openssh.enable;
      bakedFlake = c.environment.etc."nixos-install/flake".source;
      isoMatchesIsoConfig = f.iso.${name} == f.isoConfig.${name}.config.system.build.images.iso;
    };
in {
  antagony = probe "antagony";
  remembrance = probe "remembrance";
}

